P=re.compile(r"no Brasil, por exemplo,.*?por isso confirme com (?:um contador e um advogado|um advogado e um contador|um contador)")
k=0
for f in sorted(glob.glob('work/GREEN-L5-pt-PT/b*.txt')):
    t=open(f,encoding='utf-8').read()
    def rep(m):
        global k; r=S[k]; k+=1; return r
    t=P.sub(rep,t)
    open(f,'w',encoding='utf-8').write(t)
print('replaced',k,'of',len(S))
